const std = @import("std");
const language = @import("language");
const src = "def main() -> i64:\n    return 1\n";
fn check(cache: *language.semantic_cache.Cache) !void {
    var compilation = try language.Compilation.init(std.testing.allocator, "probe.my", src);
    defer compilation.deinit();
    try compilation.checkWithCache(cache);
}
test "review ordinary index budget boundary" {
    const a = std.testing.allocator;
    var full = language.semantic_cache.Cache.init(a, 1024 * 1024);
    defer full.deinit();
    try check(&full);
    const row_cost = @sizeOf(@TypeOf(full.entries[0])) + full.entries[0].arena.queryCapacity();
    const budget = row_cost + 50;
    var limited = language.semantic_cache.Cache.init(a, budget);
    defer limited.deinit();
    try check(&limited);
    const first_retained = limited.statistics.retained_bytes;
    try check(&limited);
    std.debug.print("review: row_cost={d} budget={d} first_retained={d} second_retained={d} index_capacity={d} entries={d}\n", .{row_cost,budget,first_retained,limited.statistics.retained_bytes,limited.index.capacity(),limited.entries.len});
    try std.testing.expect(limited.statistics.retained_bytes <= budget);
}
test "review owned retained allocation accounting" {
    var tracker = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    var cache = language.semantic_cache.Cache.init(tracker.allocator(), 1024 * 1024);
    defer cache.deinit();
    try check(&cache);
    const owned_bytes = tracker.allocated_bytes - tracker.freed_bytes;
    std.debug.print("review: reported={d} owned_allocator_bytes={d} undercount={d}\n", .{cache.statistics.retained_bytes,owned_bytes,owned_bytes-cache.statistics.retained_bytes});
    try std.testing.expectEqual(owned_bytes, cache.statistics.retained_bytes);
}

