 text=pathlib.Path('/proc',str(pid),'status').read_text();return int(re.search(r'VmRSS:\s+(\d+)',text)[1])
def scenario(name,vary):
 root=base/name;root.mkdir();source=root/'main.my';source.write_text(prefix+'    return sized[1000]() + 1000\n')
 err=open(root/'stderr.txt','w');p=subprocess.Popen([info['compiler'],'check-session',str(source)],cwd=base,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=err,text=True,bufsize=1)
 rows=[];start=time.monotonic()
 def action(command):
