  if not line:raise RuntimeError('session exited')
  q=json.loads(line);assert q['status']==0,q;return q
 try:
  for i in range(900):
   n=1000+i if vary else 1000;source.write_text(prefix+f'    return sized[{n}]() + {1000+i}\n');q=action('check')
