   if time.monotonic()-start>45:raise RuntimeError('bounded review timeout')
  cleared=action('clear');afterclear=rss(p.pid);q=action('check');rows.append({'after_clear_rss_kib':afterclear,'after_recheck_rss_kib':rss(p.pid),'recheck_work':q['work'],'functions':q['functions']})
  action('quit');p.wait(timeout=5)
 finally:
  if p.poll() is None:p.kill();p.wait()
  err.close()
 return {'command':[info['compiler'],'check-session',str(source)],'iterations':900,'source_prefix':prefix,'vary_length':vary,'samples':rows,'stderr':(root/'stderr.txt').read_text(),'wall_seconds':time.monotonic()-start}
doc['retention_extended_experiment']={}
for name,vary in [('retention900_fixed',False),('retention900_distinct',True)]:
